    /** First-launch welcome screen: let the user pick their AI provider with one tap. */
    void showWelcome(){
        petRow.setVisibility(View.GONE);
        ScrollView scroll=new ScrollView(this);LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(20),dp(16),dp(20),dp(20));scroll.addView(page);
        TextView title=text("Welcome to "+petName()+" ✳",28);title.setTypeface(null,Typeface.BOLD);page.addView(title);
        page.addView(text("Your gentle companion for wellbeing, learning, and goals.\n\nChoose how you'd like to talk with "+petName()+":",16));
        // Provider cards
        String[] ids={AiProvider.LOCAL,AiProvider.GEMINI,AiProvider.OPENAI,AiProvider.CLAUDE,AiProvider.CUSTOM};
        String[] titles={"🏠 On-device AI","✨ Google Gemini","💬 OpenAI API","🧠 Anthropic Claude","🔧 Custom API"};
        String[] descs={
            "Download a small local model once, then chat offline. No API key or per-message fee.",
            "Powerful AI with web search. Free tier available — just paste your key from Google AI Studio.",
            "Advanced conversational AI. Paste your OpenAI API key to connect.",
            "Thoughtful, detailed AI responses. Paste your Anthropic API key to connect.",
            "Connect a compatible HTTPS API. The server operator sets pricing and privacy."
        };
        for(int n=0;n<ids.length;n++){final String pid=ids[n];LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(rounded(n==0?PALE:SURFACE));TextView cardTitle=text(titles[n],17);cardTitle.setTypeface(null,Typeface.BOLD);card.addView(cardTitle);card.addView(text(descs[n],13));if(n==0){TextView free=text("No API key needed · device support required",13);free.setTextColor(GREEN);card.addView(free);}
            Button pick=button(n==0?"Check my phone":"Choose & Set Up",n==0);card.addView(pick);
            pick.setOnClickListener(v->{
                prefs.edit().putString("ai_provider",pid).putBoolean("welcome_done",true).apply();
                conversation.clear();
                show("Home");settings();
            });
            LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(8),0,dp(8));page.addView(card,cp);
        }
        page.addView(text("You can change your AI provider anytime in Setup.",13));
        content.removeAllViews();content.addView(scroll,new LinearLayout.LayoutParams(-1,-1));
    }
