        for(JSONObject turn:conversation)addBubble(turn.optString("role").equals("user")?"You":"Milo",turn.optJSONArray("parts").optJSONObject(0).optString("text"),false);
        if(backgroundReply!=null){GeminiReply reply=backgroundReply;String question=backgroundQuestion;backgroundReply=null;backgroundQuestion=null;addBubble("You (background voice)",question==null?"Voice question":question,false);addBubble("Milo",reply.text,false);renderSources(reply);}
        Button ideas=button("Need a starting point?",false);ideas.setBackground(rounded(Color.TRANSPARENT));ideas.setTextColor(GREEN);content.addView(ideas);ideas.setOnClickListener(v->{String[] prompts={"I want gentle support with stress. Ask what's bothering me and help me choose one small coping step, without promising to fix my mood.","Help me brainstorm realistic business ideas based on my interests. Ask about my skills, time and budget, then suggest a small low-cost experiment.","Help me build a manageable wellbeing routine. Ask my priorities. Do not diagnose me or recommend medicines.","Help me choose one small step toward my goal today, considering my energy."};new AlertDialog.Builder(this).setTitle("Let's begin with…").setItems(new String[]{"Feeling stressed","A business idea","A healthy habit","My next small step"},(d,n)->{if(!busy)input.setText(prompts[n]);}).setNegativeButton("Close",null).show();});
        status=text(busy?"Milo is thinking…":"Speak or type. Review your words before Send.",12);status.setTextColor(MUTED);content.addView(status);
