    void importLocalModel(Uri uri,String kind){if(busy)return;busy=true;android.app.ProgressDialog progress=new android.app.ProgressDialog(this);progress.setMessage("Importing local model… keep Milo open");progress.setCancelable(false);progress.show();worker.execute(()->{boolean ok=false;try{PortableLocalAi.importModel(this,uri,kind);ok=true;}catch(Exception ignored){}final boolean done=ok;handler.post(()->{busy=false;if(destroyed)return;progress.dismiss();if(done){prefs.edit().putBoolean("portable_local",true).putString("ai_provider",AiProvider.LOCAL).apply();Toast.makeText(this,"Local "+PortableLocalAi.modelName(this)+" ready to try. Open Talk.",Toast.LENGTH_LONG).show();show("Talk");}else Toast.makeText(this,"Import failed. Select the complete linked .task file and check free storage.",Toast.LENGTH_LONG).show();});});}
    void resetProviderSession(){stopService(new Intent(this,BackgroundVoiceService.class));speech.stop();prefs.edit().putBoolean("direct_voice",false).apply();conversation.clear();backgroundReply=null;backgroundQuestion=null;}
