    void testConnection(String pid,TextView result,Button button){final AiProvider provider=AiProvider.current(this);final String saved;try{saved=KeyVault.loadForProvider(this,pid);if(!provider.id().equals(pid)||saved.isEmpty()){result.setText("Select this provider and save its connection first.");return;}}catch(Exception e){result.setText("Android could not unlock the saved key. Paste and save it again.");return;}busy=true;button.setEnabled(false);result.setText("Testing saved connection… your key remains saved");worker.execute(()->{String message;try{GeminiReply reply=provider.chat(saved,"Milo","English","","Gentle","Reply with a short hello.",new ArrayList<>(),"",false,part->{});message="Connected: "+reply.text+" · Key still saved securely.";}catch(Exception e){message=e instanceof ApiFailure?e.getMessage():e instanceof java.net.UnknownHostException?"No internet or DNS connection. Your saved key has not been erased.":e instanceof java.net.SocketTimeoutException?"The provider timed out. Try later; your saved key has not been erased.":"Connection failed. Check internet, model ID and provider credits. Your saved key has not been erased.";}final String feedback=message;handler.post(()->{busy=false;if(!destroyed){result.setText(feedback);button.setEnabled(true);}});});}
    boolean speakReply(String words,String utterance,String tone){speech.speak(cleanSpeech(words),tone,utterance);return true;}
    void testSpeaker(){if(!prefs.getBoolean("pet_enabled",true)){Toast.makeText(this,"Enable Milo in Setup before testing speech.",Toast.LENGTH_SHORT).show();return;}if(!voiceReady){Toast.makeText(this,"A spoken voice is unavailable. Choose English in Setup or install a voice in Android’s text-to-speech settings.",Toast.LENGTH_LONG).show();return;}speech.stop();speech.beginReply();speech.speak("Hello. I am "+petName()+". This is your speaker test.","happy","milo-test");Toast.makeText(this,"Speaker test started. Check your media volume.",Toast.LENGTH_LONG).show();}
    void previewExpressions(){String[] states={"happy","listening","thinking","speaking","comfort","calm","curious","celebrate","playful","concerned","surprised","excited","laughing","shy","grateful","sad","confused","sleepy","oops","angry"};String[] situations={"Say hello","Listen to you","Think about a question","Speak a reply","Support a difficult day","Take a break","Learn something","Celebrate effort","Enjoy a gentle joke","Slow down after a setback","Hear surprising news","Share big news","Laugh at a joke","Get a compliment","Say thank you","Hear sad news","Ask what you mean","Say goodnight","Fix its own mistake","Pretend to be grumpy in a game"};LinearLayout demo=new LinearLayout(this);demo.setOrientation(LinearLayout.VERTICAL);demo.setPadding(dp(20),dp(12),dp(20),dp(12));PetFaceView face=new PetFaceView(this);demo.addView(face,new LinearLayout.LayoutParams(-1,dp(220)));TextView label=text("Ready when you are",16);demo.addView(label);Spinner choices=new Spinner(this);choices.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,situations));demo.addView(choices);choices.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){face.setExpression(states[pos]);label.setText(CompanionStyle.label(states[pos]));}});demo.addView(text("Preview only. This does not start the microphone or an AI request. You stay free to disagree, rest, or switch Milo off.",13));new AlertDialog.Builder(this).setTitle("Meet "+petName()).setView(demo).setPositiveButton("Done",null).show();}
    void saveKey(String key)throws Exception{KeyVault.save(this,key);}
    String loadKey()throws Exception{return KeyVault.load(this);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("open_people",false))show("People");if(intent.getBooleanExtra("pet_microphone",false))askPetMicrophone();}
    /** The floating pet needs microphone permission before its first conversation. */
    void askPetMicrophone(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)petTalk();else requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},93);}
    void petTalk(){try{startForegroundService(new Intent(this,FloatingPetService.class).setAction("TALK"));moveTaskToBack(true);}catch(RuntimeException e){Toast.makeText(this,"Android could not start the pet conversation",Toast.LENGTH_LONG).show();}}
    @Override protected void onStart(){super.onStart();foreground=true;if(peopleScreen instanceof SparkPeopleScreen)((SparkPeopleScreen)peopleScreen).resume();}
    @Override protected void onStop(){foreground=false;if(peopleScreen instanceof SparkPeopleScreen)((SparkPeopleScreen)peopleScreen).pause();super.onStop();stopBreathing();if(speech!=null)speech.stop();}
    @Override protected void onDestroy(){if(peopleScreen!=null)peopleScreen.close();destroyed=true;requestId++;stopBreathing();worker.shutdownNow();if(speech!=null)speech.shutdown();if(home!=null)home.destroy();super.onDestroy();}
